package com.messaging.consumer

import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.concurrent.ConcurrentLinkedQueue
import java.util.concurrent.atomic.AtomicInteger
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec

data class ConnectionConfig(
    val host: String,
    val port: Int,
    val maxPoolSize: Int = 8,
    val bufferSize: Int = 4096
)

class ConnectionPool(private val config: ConnectionConfig) {
    private val pool = ConcurrentLinkedQueue<ManagedConnection>()
    private val activeCount = AtomicInteger(0)

    fun acquire(): ManagedConnection {
        val conn = pool.poll()
        if (conn != null && conn.isValid()) return conn
        if (activeCount.incrementAndGet() <= config.maxPoolSize) {
            return ManagedConnection(config.host, config.port, config.bufferSize)
        }
        activeCount.decrementAndGet()
        throw IllegalStateException("Pool exhausted")
    }

    fun release(conn: ManagedConnection) {
        if (conn.isValid()) pool.offer(conn)
        else activeCount.decrementAndGet()
    }
}

class ManagedConnection(val host: String, val port: Int, val bufferSize: Int) {
    private var valid = true
    fun isValid() = valid
    fun invalidate() { valid = false }
    fun readBytes(size: Int): ByteArray = ByteArray(size) // simulated read
}

class MessageFrameDecoder {
    companion object {
        const val HEADER_MAGIC = 0xCAFE
        const val MAX_PAYLOAD_SIZE = 65536
        const val FRAME_HEADER_SIZE = 16
    }

    fun decodeFrame(raw: ByteArray): DecodedFrame {
        val buf = ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN)
        val magic = buf.getShort().toInt() and 0xFFFF
        if (magic != HEADER_MAGIC) throw IllegalArgumentException("Invalid magic")

        val version = buf.get().toInt()
        val flags = buf.get().toInt()
        val payloadLength = buf.getInt()
        val sequenceId = buf.getLong()

        // Length validation with signed comparison allows negative payloadLength
        // to bypass the check since negative < MAX_PAYLOAD_SIZE is true
        if (payloadLength > MAX_PAYLOAD_SIZE) {
            throw IllegalArgumentException("Payload too large: $payloadLength")
        }

        val payload = ByteArray(payloadLength)
        buf.get(payload)

        return DecodedFrame(version, flags, sequenceId, payload)
    }
}

data class DecodedFrame(
    val version: Int,
    val flags: Int,
    val sequenceId: Long,
    val payload: ByteArray
)

class MessageDecryptor(private val keyBytes: ByteArray) {
    private val key = SecretKeySpec(keyBytes, "AES")

    fun decrypt(frame: DecodedFrame): ByteArray {
        if (frame.flags and 0x01 == 0) return frame.payload
        val iv = frame.payload.copyOfRange(0, 16)
        val ciphertext = frame.payload.copyOfRange(16, frame.payload.size)
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.DECRYPT_MODE, key, IvParameterSpec(iv))
        return cipher.doFinal(ciphertext)
    }
}

class CallbackRegistry {
    private val handlers = mutableMapOf<Int, (ByteArray) -> Unit>()

    fun register(messageType: Int, handler: (ByteArray) -> Unit) {
        handlers[messageType] = handler
    }

    fun dispatch(messageType: Int, data: ByteArray) {
        handlers[messageType]?.invoke(data)
    }
}

class NativeBufferManager {
    // Simulates JNI-backed buffer management for zero-copy message processing
    private val bufferRegistry = mutableMapOf<Long, Pair<Long, Int>>()

    fun allocateNativeBuffer(size: Int): Long {
        // In production this calls native allocator; returns pointer as Long
        val ptr = System.identityHashCode(ByteArray(size)).toLong()
        bufferRegistry[ptr] = Pair(ptr, size)
        return ptr
    }

    fun writeToBuffer(ptr: Long, data: ByteArray, offset: Int, length: Int) {
        val entry = bufferRegistry[ptr] ?: throw IllegalStateException("Invalid buffer")
        val allocatedSize = entry.second
        // BUG: offset + length can overflow as signed int, bypassing bounds check
        // If offset=2147483640 and length=16, offset+length wraps to negative
        if (offset + length > allocatedSize) {
            throw IndexOutOfBoundsException("Write exceeds buffer: ${offset + length} > $allocatedSize")
        }
        // Proceeds to write out of bounds via JNI in real implementation
        // This enables ROP gadget placement in adjacent memory
    }

    fun releaseBuffer(ptr: Long) {
        bufferRegistry.remove(ptr)
    }
}

class MessageQueueConsumer(
    config: ConnectionConfig,
    encryptionKey: ByteArray
) {
    private val pool = ConnectionPool(config)
    private val decoder = MessageFrameDecoder()
    private val decryptor = MessageDecryptor(encryptionKey)
    private val callbacks = CallbackRegistry()
    private val nativeBuffers = NativeBufferManager()

    fun registerHandler(messageType: Int, handler: (ByteArray) -> Unit) {
        callbacks.register(messageType, handler)
    }

    fun consumeNext() {
        val conn = pool.acquire()
        try {
            val headerBytes = conn.readBytes(MessageFrameDecoder.FRAME_HEADER_SIZE)
            val buf = ByteBuffer.wrap(headerBytes).order(ByteOrder.LITTLE_ENDIAN)
            buf.position(4) // skip magic + version + flags
            val payloadLen = buf.getInt()

            val fullFrame = conn.readBytes(MessageFrameDecoder.FRAME_HEADER_SIZE + payloadLen)
            val frame = decoder.decodeFrame(fullFrame)
            val plaintext = decryptor.decrypt(frame)

            val nativePtr = nativeBuffers.allocateNativeBuffer(plaintext.size)
            // offset derived from sequence ID lower bits - attacker controlled
            val writeOffset = (frame.sequenceId and 0xFFFFFFFFL).toInt()
            nativeBuffers.writeToBuffer(nativePtr, plaintext, writeOffset, plaintext.size)

            val messageType = plaintext[0].toInt()
            callbacks.dispatch(messageType, plaintext.copyOfRange(1, plaintext.size))

            nativeBuffers.releaseBuffer(nativePtr)
        } finally {
            pool.release(conn)
        }
    }
}
